@spec tracker_page_spec  src=tests/specs/tracker_page_spec.lua  loc=1965  cases=62
@exercises tuning (tuning), commandManager (h.cmgr), configManager (h.cm), midiManager (h.mm), trackerManager (h.tm)
@surface   tuning.derive, tuning.genDiamond, cmgr:scope, cmgr:installManifest, cmgr:entry, cm:setContext, cmgr:push, cmgr:invoke, cm:getAt, cm:set, cm:get, tuning.stepToMidi, mm:subscribe, mm:notes, tm:assignEvent, tm:byUuid, tm:flush
@harness   mk, reaper:addItem, reaper:setProjectTracks, reaper:seedMidi

# Intent
  Pin-tests for trackerPage's Page interface (bind / unbind / focusState /
  bind-from-cursor) and the retune modal's slots, defaults and dispatch.
  render / handleInput are stubs wired in step 3 and verified in REAPER, not here.

# Helpers
  @fn resetArrange()  @ 56-182
  @fn seedItems(h, takes, srcLen)  @ 198-203
      -- A bind re-keys cm's track tier off the take's own item, so a take named in
      -- fakeArrange needs one in the fake project too.
  @fn newTrackerPage(cm, ds, cmgr, chrome, gui, help)  @ 205-214
  @fn trackList(trackCount)  @ 216-222
  @fn mapBox(tv, take)  @ 225-229
      -- The box the map draws for a take: the travel consumes the window's own shapes.
  @fn mapTracker(harness, inst, trackCount)  @ 234-248
      -- A tracker bound to the take 'i0' over a track list of the given width, with
      -- i0's placement as the caller states it; inst = nil binds it into no instance.
      -- Returns the page's tv, the harness behind it for the cmgr, and the page itself.
  @fn chaseTracker(harness)  @ 252-277
      -- A tracker on track 0, bound to 'a0' in its first slot: 'b8' fills the second slot
      -- at QN 8, an audio item lies at 16, and 'c4' sits on the track beside it at 4.

# Cases
  @case 'the manifest declares every command the tracker page registers'  [harness]  @ 284-305
  @case 'every command in the page\'s F1 groups resolves to a manifest entry'  [harness]  @ 311-327
  @case 'bind(take) drives cm:setContext via the page's own tm:bindTake'  [harness]  @ 331-339
  @case 'unbind() drives cm:setContext(nil) via the page's own tm:bindTake'  [harness]  @ 342-351
  @case 'focusState before any render returns both bits false'  [harness]  @ 354-361
  @case 'bindFromSelection binds tm to the resolved selection take, drops when the track has no slots'  [harness]  @ 367-380
  @case 'with no live instance, the new take mints a parked slot and selects it'  [harness]  @ 384-401
  @case 'deleteBoundSlot confirms, then deletes the bound slot through the arrange facade'  [harness]  @ 407-428
  @case 'take properties renames the bound take\'s slot, not that one take'  [harness]  @ 434-452
  @case 'take properties follows the bound take when the tracker sits on another slot'  [harness]  @ 459-477
  @case 'the new take places below the current instance and becomes current'  [harness]  @ 483-516
  @case 'a new take on a just-selected track parks, rather than appending on the old one'  [harness]  @ 520-544
  @case 'duplicate below appends another instance of the bound slot and makes it current'  [harness]  @ 550-580
  @case 'duplicate below refuses where the free span falls short'  [harness]  @ 584-605
  @case 'duplicate below on a slot whose only take is parked does nothing'  [harness]  @ 609-622
  @case 'the variant step rebinds the tracker to the slot stepped to and follows its placement'  [harness]  @ 628-662
  @case 'a variant step with the tracker in no instance does nothing'  [harness]  @ 666-680
  @case 'prev/next track + take drive the tv selection, not the arrange cursor'  [harness]  @ 684-707
  @case 'a track step lands on the placement overlapping the current instance most'  [harness]  @ 711-747
  @case 'with nothing overlapping, a track step lands on the placement nearest in time'  [harness]  @ 751-786
  @case 'F6 plays from the instance dived into, not the placement the bind resolved'  [harness]  @ 793-810
  @case 'a dive outranks a play head already sitting in another instance'  [harness]  @ 814-837
  @case 'the play head entering an instance makes it current; leaving one writes nothing'  [harness]  @ 841-864
  @case 'with follow on, the play head carries the tracker across the bound track's slots'  [harness]  @ 870-885
  @case 'with follow off, the head entering another slot leaves the tracker where it was'  [harness]  @ 889-896
  @case 'the chase brackets no loop and raises no map tab'  [harness]  @ 900-915
  @case 'a slot change seeks from the outgoing instance, backwards for prevTake'  [harness]  @ 919-954
  @case 'the walk steps along the track's placements in start order, holding at the ends'  [harness]  @ 958-1006
  @case 'a walk into another slot resets the caret; within one slot the caret holds'  [harness]  @ 1010-1047
  @case 'deleting the instance drops that placement and lands on the one before it'  [harness]  @ 1051-1085
  @case 'a slot with no live instance leaves the tracker nowhere, and F6 silent'  [harness]  @ 1089-1105
  @case 'the map window centres the bound column, and clamps it at both ends'  [harness]  @ 1114-1132
  @case 'the map window pages time, a start in the last bar opening the next page'  [harness]  @ 1136-1152
  @case 'while following, the map window pages off the play head'  [harness]  @ 1156-1166
  @case 'with the tracker in no instance the map window pages on the edit cursor'  [harness]  @ 1170-1177
  @case 'the map window carries the takes over it, the current instance marked'  [harness]  @ 1181-1192
  @case 'the map window carries the transport it meets, and only that'  [harness]  @ 1196-1219
  @case 'the map loop candidate snaps to the cell, widens to one, and holds at 0'  [harness]  @ 1223-1242
  @case 'the map drives the transport, and a hand-set loop drops loop to item'  [harness]  @ 1246-1257
  @case 'a click on a map box travels to its instance, across tracks as well as slots'  [harness]  @ 1261-1300
  @case 'a map box that is no stop refuses the travel, as the walk passes it over'  [harness]  @ 1304-1318
  @case 'the pin key holds the map up as the palette default, and drops it when pressed again'  [harness]  @ 1322-1331
  @case 'a gesture raises the map, and it falls at the next command'  [harness]  @ 1335-1376
  @case 'the play row is the head\'s offset into the current instance, in rows'  [harness]  @ 1380-1407
  @case 'while following, the grid pages the scroll to hold the play row'  [harness]  @ 1411-1457
  @case 'the play row dims where the head is sounding a sibling instance'  [harness]  @ 1461-1485
  @case 'the cut row is where the rendered span stops short of the source'  [harness]  @ 1492-1513
  @case 'the play row and the head row count from the source origin, not the start'  [harness]  @ 1519-1543
  @case 'a dive carries the arrange QN to the caret row, and the caret hands it back'  [harness]  @ 1550-1569
  @case 'a caret outside the rendered span hands back the row the span stops at'  [harness]  @ 1573-1592
  @case 'leaving the tracker puts the arrange caret where the tracker caret is'  [harness]  @ 1596-1618
  @case 'with loop to item on, a dive brackets the instance dived into'  [harness]  @ 1624-1642
  @case 'the play head entering an instance leaves the loop where it was'  [harness]  @ 1646-1664
  @case 'the toggle command brackets the current instance as it comes on'  [harness]  @ 1668-1690
  @case 'Esc clears the loop and drops loop to item with it'  [harness]  @ 1694-1705
  @case 'the loop-to-item verb brackets the current instance, toggle or no toggle'  [harness]  @ 1709-1733
  @case 'retune opens on the scope the selection implies and OK snaps that scope'  [harness]  @ 1739-1794
  @case 'retune opens on the facility the take carries, its dials on their figures'  [harness]  @ 1802-1831
  @case 'a refused retune offers to widen, and the offer taken solves again'  [harness]  @ 1837-1880
  @case 'empty grid shows the single no-takes message'  [harness]  @ 1886-1900
  @case 'an owned tm flush resyncs the watcher baseline; only a foreign write trips the reload'  [harness]  @ 1907-1939
  @case 'bindFromSelection re-keys cm on return from dormancy even when the take is unchanged'  [harness]  @ 1943-1963

